// MakeTemplateValueError is a TemplateValueError of the kind, the message, the status, the errno, which a test of another
// repository raises from a callback unit of template (B2.489, GN-15d). A kind that is no kind of TemplateValueError is kind
// invalid_argument_type, and a message that is not UTF-8 kind invalid_text (GN-7a).
func MakeTemplateValueError(kind, message string, status, errno *int) (*TemplateValueError, error) {
	if !utf8.ValidString(message) {
		return nil, &TemplateValueError{failure{message: "the message of TemplateValueError is not UTF-8", kind: "invalid_text"}}
	}
	f := failure{message: message, kind: kind}
	if status != nil {
		f.status, f.hasStatus = *status, true
	}
	if errno != nil {
		f.errno, f.hasErrno = *errno, true
	}
	switch kind {
	case "lex_invalid_utf8", "parse_unterminated_tag", "parse_unterminated_comment", "parse_unterminated_string", "parse_unexpected_token", "parse_invalid_number", "parse_invalid_escape", "parse_unexpected_close", "parse_unclosed_block", "parse_else_outside_block", "parse_duplicate_else", "parse_elseif_after_else", "parse_elseif_not_in_if", "parse_reserved_name", "parse_invalid_path", "parse_invalid_block_tag", "parse_invalid_wrapper", "parse_invalid_directive", "load_not_found", "load_cycle", "load_outside_root", "load_not_loaded", "data_number_range", "data_number_not_finite", "data_invalid_utf8", "data_depth", "data_invalid_json", "runtime_compare", "runtime_div_zero", "runtime_stringify", "runtime_unknown_function", "runtime_host_function", "runtime_unknown_loop", "runtime_block_undefined", "runtime_block_redefined", "runtime_depth", "runtime_limit", "argument_delimiters", "argument_function_name", "argument_source_range", "argument_indent", "format_html", "ast_invalid", "invalid_number", "invalid_text", "invalid_path", "expected_value", "expected_digit", "expected_colon", "expected_delimiter", "expected_object_key", "invalid_escape", "invalid_unicode_escape", "unfinished_escape", "unterminated_string", "unescaped_control_character", "invalid_utf8", "maximum_depth_exceeded", "trailing_input", "duplicate_object_key", "invalid_number_literal", "depth_limit_out_of_range", "invalid_code_unit", "unpaired_surrogate", "non_finite_number":
		e := &TemplateValueError{f}
		return e, nil
	}
	return nil, &TemplateTypeError{failure{message: fmt.Sprintf("%q is no kind of TemplateValueError", kind), kind: "invalid_argument_type"}}
}

