// The static library calls these exports through C (B-8). The initializer takes the value of each, so a call graph
// of the Go code alone, such as that of deadcode, reaches them and what they call (GN-15h).
var _ = [...]any{
	polyspec_template___go_host,
	polyspec_template___go_release,
	polyspec_template___go_native,
	polyspec_template___go_keep,
	polyspec_template___go_end,
	polyspec_template___go_function,
	polyspec_template___go_release_raised,
}
